      expect(latest, isNotNull);
      expect(latest!.entries, hasLength(2));
      expect(latest.entries.last.text, _askText);
      // Round-trip fidelity.
      expect(
        ObligationsLedger.fromPayload(latest.toPayload()).toPayload(),
        latest.toPayload(),
      );
    });

