}) async {
  final hasStructured = path.any(
    (entry) => entry is HiddenRangeRecord || entry is CompactCheckpointRecord,
  );
  if (!hasStructured) {
    if (classicHidden.isEmpty) {
      return _withObligationsBlock([
        for (final entry in path) ..._entryToMessages(entry),
