+  /// — a forward-versioned entry must stay visible, never vanish.
+  static ObligationKind fromName(Object? name) => switch (name) {
+    'owner-rule' => ownerRule,
+    'agent-commitment' => agentCommitment,
+    'pending-wait' => pendingWait,
+    _ => openAsk,
+  };
