+
+  /// The payload spelling.
+  String get jsonName => name;
+
+  /// Tolerant parse (E6): unknown or missing names default to [open].
+  static ObligationStatus fromName(Object? name) => switch (name) {
+    'done' => done,
+    'superseded' => superseded,
+    _ => open,
+  };
