      final ledger = ObligationsLedger.fromPayload([
        {'text': 'legacy entry'},
        'junk-string',
        {
          'kind': 'brand-new-kind',
          'text': 'future entry',
          'status': 'brand-new-status',
        },
        {'kind': 'pending-wait', 'text': 'armed watch', 'status': 'open'},
