  }
  final entries = await getEntries();
  final seqs = RecordSeqIndex(entries);
  return _withObligationsBlock(
    renderStructuredMessages(
      path: path,
      seqs: seqs,
      projectEntry: (record) =>
          _entryToMessages(record, classicHidden: classicHidden, seqs: seqs),
    ),
    entries: entries,
  );
}

